SELECT game_id AS "gameId", type_id AS "typeId", target_category AS "targetCategory", target_id AS "targetId", extend::text AS extend, change_revision AS "changeRevision", updated_at AS "updatedAt" FROM public.type_relations WHERE game_id = #{gameId}
AND type_id = #{typeId}
AND target_category = #{targetCategory}
AND target_id = #{targetId}
ORDER BY type_id, target_category, target_id

 SELECT
game_id AS "gameId",
type_id AS "typeId",
target_category AS "targetCategory",
target_id AS "targetId",
extend::text AS extend,
change_revision AS "changeRevision",
updated_at AS "updatedAt"
 FROM public.type_relations
 WHERE game_id = #{gameId}
   AND type_id = #{typeId}
   AND target_category = #{targetCategory}
   AND target_id = #{targetId}
